const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Villarrica location (Chile)
  const villarrica = ee.Geometry.Point([-71.92, -39.28]);
  const bufferGeom = villarrica.buffer(50000); // 50km buffer

  // 2. Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // 3. Filter for 2021 (Jan 1 - Dec 31)
  const rainfall2021 = chirps
    .filterDate('2021-01-01', '2022-01-01')
    .filterBounds(bufferGeom);

  // 4. Filter for 2016 (Jan 1 - Dec 31, 5 years prior)
  const rainfall2016 = chirps
    .filterDate('2016-01-01', '2017-01-01')
    .filterBounds(bufferGeom);

  // 5. Check collection sizes
  const size2021 = rainfall2021.size().getInfo();
  const size2016 = rainfall2016.size().getInfo();

  if (size2021 === 0 || size2016 === 0) {
    print(`2021 Images: ${size2021}, 2016 Images: ${size2016}`);
    print("C1");
    return;
  }

  // 6. Calculate total rainfall for 2021
  const totalRain2021Img = rainfall2021.sum();
  const stats2021 = totalRain2021Img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: bufferGeom,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const rain2021 = stats2021.precipitation;

  // 7. Calculate total rainfall for 2016
  const totalRain2016Img = rainfall2016.sum();
  const stats2016 = totalRain2016Img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: bufferGeom,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const rain2016 = stats2016.precipitation;

  // 8. Validation
  if (rain2021 === null || rain2016 === null || rain2021 === undefined || rain2016 === undefined) {
    print(`2021: ${rain2021}, 2016: ${rain2016}`);
    print("C3");
    return;
  }

  if (rain2021 < 0 || rain2016 < 0) {
    print(`Invalid rainfall values: 2021=${rain2021}, 2016=${rain2016}`);
    print("C3");
    return;
  }

  // 9. Print results
  print(`Images 2021: ${size2021}, Images 2016: ${size2016}`);
  print(`Total Rainfall 2021: ${rain2021.toFixed(1)} mm`);
  print(`Total Rainfall 2016: ${rain2016.toFixed(1)} mm`);
  print(`Difference: ${(rain2021 - rain2016).toFixed(1)} mm`);

  // 10. Compare and output answer
  if (rain2021 > rain2016) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
